function SpireMixin(target, ...sources) {
    sources.forEach(source => {
      for (let key in source) {
        if (!target.hasOwnProperty(key)) {
          target[key] = source[key];
        } else {
          /*console.warn(`Property or method "${key}" already exists in target object. Skipping mixin.`);*/
        }
      }
    });
    return target;
  }

const SpireRegistry = new FinalizationRegistry(heldValue => {
    //console.log('Object is being finalized:', heldValue);
    const Spire_FreeHandle = Module.cwrap("Spire_FreeHandle", "", ["number"]);
    Spire_FreeHandle(heldValue[0]);
    Module._free(heldValue[1]);
    }
);
/**
* Spire Object
*/
class spirepresentationSpireObject {
    constructor(handle) {
        this._error = Module._malloc(Module.HEAP32.BYTES_PER_ELEMENT);
        Module.HEAP32[this._error>>2] = 0;
        if(handle > 0){
            this._handle = handle;
            SpireRegistry.register(this, [this._handle, this._error]);
        }
    }

    get H() {
        return this._handle;
    }
    _setHandle(handle){
        this._handle = handle;
        if(handle > 0){
          SpireRegistry.register(this, [this._handle, this._error]);
        }
    }
    get EH() {
        Module.HEAP32[this._error>>2] = 0;
        return this._error;
    }
    get E(){
        return Module.HEAP32[this._error>>2];
    }
}
